/// <summary>
/// Reusable world-space interaction tag. Drop this component on any interactable that implements
/// <see cref="IInteractionPromptProvider"/> (pickup, grapple anchor, NPC…). On first show it spawns
/// a billboarded TextMeshPro label as a child sub-object that floats above the interactable and
/// reads "[E] Pick Up Wrench", "[Q] Grapple", etc.
///
/// It does NOT detect hover itself. <see cref="WorldInteractTagPresenter"/> reads the single hover
/// source (<see cref="PlayerMouseAimer.HoveredInteractable"/>) and calls <see cref="Show"/> /
/// <see cref="Hide"/> on the hovered object's tag — so there is exactly one tag visible at a time
/// and no per-object raycast.
/// </summary>
public class WorldInteractTag : MonoBehaviour
{
    [Tooltip("Local offset of the tag above the interactable's origin (world units, Y up).")]
    [SerializeField] private Vector3 _worldOffset = new Vector3(0f, 1.5f, 0f);
    [Tooltip("TMP point size of the world label.")]
    [SerializeField] private float _fontSize = 4f;
    [Tooltip("Face colour of the label text.")]
    [SerializeField] private Color _textColor = Color.white;
    [Tooltip("Optional pre-authored label child. Leave empty to auto-build one at runtime.")]
    [SerializeField] private TextMeshPro _label;

    private Transform _tagRoot;

    /// <summary>True while the tag is currently displayed.</summary>
    public bool IsShown => _tagRoot != null && _tagRoot.gameObject.activeSelf;

    /// <summary>Show the tag with the given display text (e.g. the prompt's Display string).</summary>
    public void Show(string text)
    {
        EnsureBuilt();
        if (_label != null) _label.text = text;
        if (_tagRoot != null) _tagRoot.gameObject.SetActive(true);
    }

    /// <summary>Hide the tag. Safe to call when already hidden.</summary>
    public void Hide()
    {
        if (_tagRoot != null) _tagRoot.gameObject.SetActive(false);
    }

    // ── Private ───────────────────────────────────────────────────────────────

    /// <summary>
    /// Build the label sub-object once. If a label was assigned in the Inspector its existing
    /// GameObject is reused; otherwise a child "InteractTag" with a TextMeshPro + Billboard is created.
    /// </summary>
    private void EnsureBuilt()
    {
        if (_tagRoot != null) return;

        if (_label != null)
        {
            _tagRoot = _label.transform;
            return;
        }

        var go = new GameObject("InteractTag");
        _tagRoot = go.transform;
        _tagRoot.SetParent(transform, worldPositionStays: false);
        _tagRoot.localPosition = _worldOffset;

        _label = go.AddComponent<TextMeshPro>();
        _label.text = string.Empty;
        _label.fontSize = _fontSize;
        _label.color = _textColor;
        _label.alignment = TextAlignmentOptions.Center;
        _label.enableWordWrapping = false;
        // Keep the mesh small and centred; the RectTransform drives TMP bounds.
        var rt = _label.rectTransform;
        rt.sizeDelta = new Vector2(6f, 1.5f);

        go.AddComponent<Billboard>();
        go.SetActive(false);
    }
}

using UnityEngine;

/// <summary>
/// Shared configuration for the 2.5D sprite depth-sorting system.
/// Assign one asset to both SpriteSortingManager (camera setup) and every
/// SortableSprite (per-object order computation) so they stay in sync.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Sprite Sorting Config")]
public class SpriteSortingConfigSO : ScriptableObject
{
    [Tooltip(
        "World-space axis along which depth is measured — positive = further away.\n\n" +
        "Leave as (0,0,0) to let SpriteSortingManager derive it from the camera's\n" +
        "forward vector at runtime (recommended).\n\n" +
        "Manual examples:\n" +
        "  Pure Z top-down  : (0, 0, 1)\n" +
        "  45° tilted camera: (0, 0.71, 0.71)\n" +
        "  60° tilted camera: (0, 0.87, 0.50)")]
    [SerializeField] private Vector3 _sortAxis = Vector3.zero;

    [Tooltip("Number of sorting-order integers per world unit of depth.\n" +
             "100 → 0.01 wu resolution (good for a 100-tile map).")]
    [Min(1f)]
    public float stepsPerUnit = 100f;

    [Tooltip("Constant added to every computed order.  Increase if you need " +
             "sprite layers to sit above other non-sprite renderers in the scene.")]
    public int baseOrder = 0;

    // ── Runtime ──────────────────────────────────────────────────────────────

    /// <summary>
    /// The normalised sort axis used at runtime.
    /// If _sortAxis is zero, falls back to Camera.main.transform.forward.
    /// SortableSprite and SpriteSortingManager both read this.
    /// </summary>
    public Vector3 SortAxisNormalized
    {
        get
        {
            if (_sortAxis.sqrMagnitude > 0.001f)
                return _sortAxis.normalized;

            // Auto-derive from camera
            if (Camera.main != null)
                return Camera.main.transform.forward;

            return Vector3.forward; // safe fallback
        }
    }

    /// <summary>Allows SpriteSortingManager to push the camera-derived axis back in.</summary>
    public void SetDerivedAxis(Vector3 axis)
    {
        if (_sortAxis.sqrMagnitude < 0.001f)
            return; // only override when axis is set to "auto"
        // No-op when the designer has set an explicit axis.
    }
}

using UnityEngine;
using UnityEngine.Rendering;

/// <summary>
/// Drop this on any scene GameObject (e.g. a "SpriteSortingManager" empty GO).
///
/// What it does
/// ────────────
/// 1. Configures Camera.main's transparency sort mode to CustomAxis so Unity's
///    renderer natively sorts all transparent draw calls (sprites, particles) by
///    their projection onto the sort axis — zero per-frame C# cost.
///
/// 2. Exposes the same SpriteSortingConfigSO used by SortableSprite so both
///    mechanisms always use the same axis and are never out of sync.
///
/// When to add SortableSprite as well
/// ────────────────────────────────────
/// Camera sort mode handles objects on the same sorting layer+order perfectly.
/// Add SortableSprite to any prefab (character, tree, NPC) where you need
/// explicit integer sortingOrder control across heterogeneous objects.
/// </summary>
public class SpriteSortingManager : MonoBehaviour
{
    [SerializeField] private SpriteSortingConfigSO _config;

    [Tooltip("When enabled the manager re-applies the camera sort axis every frame.\n" +
             "Only needed if the camera rotates during play. Leave off for a fixed camera.")]
    [SerializeField] private bool _updateEachFrame = false;

    private Camera _cam;

    private void Awake()
    {
        _cam = Camera.main;
        Apply();
    }

    private void LateUpdate()
    {
        if (_updateEachFrame)
            Apply();
    }

    private void Apply()
    {
        if (_config == null || _cam == null) return;

        Vector3 axis = _config.SortAxisNormalized;

        // Unity-native: sorts all transparent renderers on the same layer by depth.
        _cam.transparencySortMode = TransparencySortMode.CustomAxis;
        _cam.transparencySortAxis = axis;
    }

#if UNITY_EDITOR
    private void OnValidate()
    {
        // Refresh in Edit mode so the Gizmo reflects current settings immediately.
        _cam = Camera.main;
        if (_config != null && _cam != null)
            Apply();
    }

    private void OnDrawGizmosSelected()
    {
        if (_config == null) return;

        Vector3 axis = _config.SortAxisNormalized;
        Vector3 origin = transform.position + Vector3.up * 0.5f;

        Gizmos.color = new Color(0.3f, 0.8f, 1f, 0.9f);
        Gizmos.DrawRay(origin, axis * 3f);

        // Draw a small disc perpendicular to axis (shows the "ground plane" of depth)
        Vector3 perp = Vector3.Cross(axis, Vector3.up);
        if (perp.sqrMagnitude < 0.001f) perp = Vector3.right;
        perp.Normalize();
        Gizmos.color = new Color(0.3f, 0.8f, 1f, 0.3f);
        for (int i = 0; i < 16; i++)
        {
            float a0 = i * Mathf.PI * 2f / 16f;
            float a1 = (i + 1) * Mathf.PI * 2f / 16f;
            Vector3 v0 = origin + Quaternion.AngleAxis(a0 * Mathf.Rad2Deg, axis) * perp;
            Vector3 v1 = origin + Quaternion.AngleAxis(a1 * Mathf.Rad2Deg, axis) * perp;
            Gizmos.DrawLine(v0, v1);
        }
    }
#endif
}

using System;
using UnityEngine;

/// <summary>
/// Single source of truth for the mouse pointer. One per scene (lives on the UI manager object).
/// Every frame it reads the cursor, builds ONE world ray, and casts ONCE against a combined layer
/// mask — then caches the result. Gameplay and UI read these cached values instead of each running
/// their own <c>Camera.ScreenPointToRay(Input.mousePosition)</c> + <c>Physics.Raycast</c>.
///
/// Same hub idea as the other managers: record the signal once, everyone else just reads it. Runs
/// early (negative execution order) so the cache is fresh before any default-order consumer's Update.
/// </summary>
[DefaultExecutionOrder(-90)]
public class MousePointer : MonoBehaviour
{
    public static MousePointer Instance { get; private set; }

    [Tooltip("Camera the cursor ray is built from. Falls back to Camera.main.")]
    [SerializeField] private Camera _camera;
    [Tooltip("Combined mask for the per-frame world cast — the union of everything UI/gameplay needs.")]
    [SerializeField] private LayerMask _worldMask = ~0;
    [SerializeField] private float _maxDistance = 100f;

    // ── Cached each frame ───────────────────────────────────────────────────────

    /// <summary>Cursor position in screen pixels (== Input.mousePosition).</summary>
    public Vector2 ScreenPosition { get; private set; }
    /// <summary>Ray from the camera through the cursor.</summary>
    public Ray WorldRay { get; private set; }
    /// <summary>True if this frame's cast hit a collider on <see cref="_worldMask"/>.</summary>
    public bool HasHit { get; private set; }
    /// <summary>This frame's raycast hit (valid only when <see cref="HasHit"/>).</summary>
    public RaycastHit Hit { get; private set; }
    /// <summary>Hit point if we hit, else the ray projected to max distance (always usable as an aim target).</summary>
    public Vector3 WorldPoint { get; private set; }
    /// <summary>Collider under the cursor this frame, or null.</summary>
    public Collider HoverCollider { get; private set; }
    /// <summary>GameObject under the cursor this frame, or null.</summary>
    public GameObject HoverObject { get; private set; }

    /// <summary>Fires when the hovered GameObject changes (including to/from null).</summary>
    public event Action<GameObject> OnHoverChanged;

    private GameObject _lastHover;

    // ── Public helpers ──────────────────────────────────────────────────────────

    /// <summary>True when the current hover object sits on one of the given layers.</summary>
    public bool HoverOnLayers(LayerMask mask)
        => HoverObject != null && (mask.value & (1 << HoverObject.layer)) != 0;

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[MousePointer] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
        if (_camera == null) _camera = Camera.main;
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (_camera == null)
        {
            _camera = Camera.main;
            if (_camera == null) return;
        }

        ScreenPosition = Input.mousePosition;
        WorldRay = _camera.ScreenPointToRay(ScreenPosition);

        HasHit = Physics.Raycast(WorldRay, out RaycastHit hit, _maxDistance, _worldMask, QueryTriggerInteraction.Ignore);
        Hit = hit;

        if (HasHit)
        {
            WorldPoint = hit.point;
            HoverCollider = hit.collider;
            HoverObject = hit.collider != null ? hit.collider.gameObject : null;
        }
        else
        {
            WorldPoint = WorldRay.GetPoint(_maxDistance);
            HoverCollider = null;
            HoverObject = null;
        }

        if (HoverObject != _lastHover)
        {
            _lastHover = HoverObject;
            OnHoverChanged?.Invoke(HoverObject);
        }
    }
}

