using UnityEngine;

/// <summary>
/// Directional swipe arc for the wrench. The arc lies in a plane perpendicular
/// to the camera so it appears as a perfect circle from the viewer — like a
/// ring swinging around the character sprite. Fully code-driven; no Animator.
/// </summary>
[RequireComponent(typeof(LineRenderer))]
public class WrenchSwingArc : MonoBehaviour
{
    [SerializeField] private float _radius = 1.8f;
    [SerializeField] private float _sweepAngle = 120f;
    [SerializeField] private float _duration = 0.3f;
    [SerializeField] private float _fadeOut = 0.12f;
    [SerializeField] private float _arcHeight = 0.8f;

    private LineRenderer _lr;
    private Camera _cam;
    private bool _playing;
    private float _timer;
    private float _facingAngle;
    private Vector3 _camRight;
    private Vector3 _camUp;
    private Vector3 _camForward;

    private void Awake()
    {
        _lr = GetComponent<LineRenderer>();
        _lr.useWorldSpace = true;
        _lr.startWidth = 0.08f;
        _lr.endWidth = 0.04f;
        _lr.positionCount = 0;
        _lr.enabled = false;
    }

    public void Play(Vector3 worldDirection)
    {
        CacheCameraBasis();

        // Project aim direction onto the camera's view plane
        Vector3 projected = Vector3.ProjectOnPlane(worldDirection, _camForward);
        if (projected.sqrMagnitude < 0.001f) projected = _camUp;
        projected.Normalize();

        // Facing angle within the camera plane (rotation around cam forward)
        _facingAngle = Vector3.SignedAngle(_camUp, projected, _camForward);

        _timer = 0f;
        _playing = true;
        _lr.enabled = true;
    }

    private void Update()
    {
        if (!_playing) return;

        _timer += Time.deltaTime;
        float total = _duration + _fadeOut;

        if (_timer >= total)
        {
            _playing = false;
            _lr.enabled = false;
            return;
        }

        // Keep basis fresh in case camera moves
        CacheCameraBasis();

        float t = Mathf.Clamp01(_timer / _duration);

        // Arc centre at the character's chest height
        Vector3 origin = transform.position + Vector3.up * _arcHeight;

        // Rotation that aligns the arc's "forward" with the aim direction
        Quaternion facingRot = Quaternion.AngleAxis(_facingAngle, _camForward);

        float half = _sweepAngle / 2f;
        float currentEnd = Mathf.Lerp(-half, half, t);

        int segments = 16;
        _lr.positionCount = segments + 1;
        for (int i = 0; i <= segments; i++)
        {
            float angle = Mathf.Lerp(-half, currentEnd, (float)i / segments) * Mathf.Deg2Rad;
            Vector3 arcPoint = Mathf.Sin(angle) * _radius * _camRight
                             + Mathf.Cos(angle) * _radius * _camUp;
            arcPoint = facingRot * arcPoint;
            _lr.SetPosition(i, origin + arcPoint);
        }

        // Fade out after sweep
        float alpha = _timer <= _duration ? 1f : 1f - (_timer - _duration) / _fadeOut;
        _lr.startColor = new Color(1f, 0.9f, 0.6f, alpha);
        _lr.endColor = new Color(1f, 0.9f, 0.6f, alpha * 0.5f);
    }

    private void CacheCameraBasis()
    {
        if (_cam == null) _cam = Camera.main;
        if (_cam == null) return;
        _camRight   = _cam.transform.right;
        _camUp      = _cam.transform.up;
        _camForward = _cam.transform.forward;
    }
}

