var player = UnityEngine.GameObject.Find("Player");
var swingLine = player.transform.Find("SwingLine");
if (swingLine == null) { UnityEngine.Debug.LogError("SwingLine child not found"); return; }

var swingArc = swingLine.GetComponent<WrenchSwingArc>();
if (swingArc == null) { UnityEngine.Debug.LogError("WrenchSwingArc not found on SwingLine"); return; }

var swingController = player.GetComponent<WrenchSwingController>();
if (swingController == null) { UnityEngine.Debug.LogError("WrenchSwingController not found on Player"); return; }

// Use SerializedObject to set the private serialized field
var so = new UnityEditor.SerializedObject(swingController);
var prop = so.FindProperty("_swingArc");
if (prop == null) { UnityEngine.Debug.LogError("_swingArc property not found"); return; }
prop.objectReferenceValue = swingArc;
so.ApplyModifiedProperties();

UnityEngine.Debug.Log($"Wired _swingArc on WrenchSwingController -> {swingArc.gameObject.name}");

