var player = UnityEngine.GameObject.Find("Player");
var swingLine = player.transform.Find("SwingLine");
var lr = swingLine.GetComponent<UnityEngine.LineRenderer>();
if (lr == null) { UnityEngine.Debug.LogError("No LineRenderer on SwingLine"); return; }

// Set up a default material (the built-in LineRenderer material)
lr.material = new UnityEngine.Material(UnityEngine.Shader.Find("Unlit/Color")) { color = new UnityEngine.Color(1f, 0.9f, 0.6f, 1f) };
lr.useWorldSpace = true;
lr.startWidth = 0.08f;
lr.endWidth = 0.04f;
lr.positionCount = 0;
lr.enabled = false;
lr.numCornerVertices = 4;
lr.numCapVertices = 4;

UnityEngine.Debug.Log("LineRenderer configured on SwingLine");

