// Find Player_Proc (may be inactive) and remove stale WrenchSwingArc + LineRenderer
var allTransforms = UnityEngine.Resources.FindObjectsOfTypeAll<UnityEngine.Transform>();
int removed = 0;
foreach (var t in allTransforms)
{
    if (t == null) continue;
    var arc = t.GetComponent<WrenchSwingArc>();
    if (arc == null) continue;

    // Keep the one on SwingLine under Player
    if (t.name == "SwingLine" && t.parent != null && t.parent.name == "Player")
        continue;

    UnityEngine.Debug.Log($"Removing stale WrenchSwingArc from: {t.name} (parent: {(t.parent != null ? t.parent.name : "none")})");

    // Also remove the auto-added LineRenderer
    var lr = t.GetComponent<UnityEngine.LineRenderer>();
    if (lr != null) UnityEngine.Object.DestroyImmediate(lr);

    UnityEngine.Object.DestroyImmediate(arc);
    removed++;
}
UnityEngine.Debug.Log($"Cleaned up {removed} stale WrenchSwingArc(s)");

