using UnityEngine;

/// <summary>
/// Placeholder wrench swing VFX: a slash line that draws from the player toward
/// the hit point, plus a small starburst at the endpoint. Both fade out.
/// Replaces the old ring-arc approach. Will be swapped for real sprite anims later.
/// </summary>
[RequireComponent(typeof(LineRenderer))]
public class WrenchSwingArc : MonoBehaviour
{
    [Header("Slash Line")]
    [SerializeField] private float _slashDrawTime = 0.1f;
    [SerializeField] private float _slashFadeTime = 0.15f;
    [SerializeField] private float _slashWidth = 0.1f;

    [Header("Burst")]
    [SerializeField] private float _burstMaxRadius = 0.5f;
    [SerializeField] private float _burstExpandTime = 0.1f;
    [SerializeField] private float _burstFadeTime = 0.2f;
    [SerializeField] private int _burstRays = 6;

    [Header("Common")]
    [SerializeField] private float _arcHeight = 0.8f;
    [SerializeField] private Color _slashColor = new Color(1f, 0.9f, 0.6f);
    [SerializeField] private Color _burstColor = new Color(1f, 0.7f, 0.3f);

    private LineRenderer _slashLr;
    private LineRenderer _burstLr;
    private bool _playing;
    private float _timer;
    private Vector3 _startPos;
    private Vector3 _hitPos;

    private void Awake()
    {
        // First LineRenderer = slash line
        _slashLr = GetComponent<LineRenderer>();
        SetupLr(_slashLr, _slashWidth, _slashWidth * 0.4f);

        // Second LineRenderer = burst starburst
        var burstGo = new GameObject("Burst");
        burstGo.transform.SetParent(transform, false);
        _burstLr = burstGo.AddComponent<LineRenderer>();
        SetupLr(_burstLr, _slashWidth * 0.6f, _slashWidth * 0.2f);

        HideAll();
    }

    private static void SetupLr(LineRenderer lr, float startW, float endW)
    {
        lr.useWorldSpace = true;
        lr.startWidth = startW;
        lr.endWidth = endW;
        lr.positionCount = 0;
        lr.enabled = false;
        lr.numCornerVertices = 2;
        lr.numCapVertices = 2;
        // Default material (will be coloured per-frame)
        lr.material = new Material(Shader.Find("Unlit/Color")) { color = Color.white };
    }

    /// <summary>
    /// Fire the slash + burst. worldAimPoint is the ground-plane point under the cursor.
    /// Burst is placed at the exact cursor hit so it lines up with the mouse.
    /// </summary>
    public void Play(Vector3 worldAimPoint)
    {
        _startPos = transform.position + Vector3.up * _arcHeight;
        _hitPos = worldAimPoint;

        _timer = 0f;
        _playing = true;
    }

    private void Update()
    {
        if (!_playing) return;

        _timer += Time.deltaTime;

        float slashTotal = _slashDrawTime + _slashFadeTime;
        float burstTotal = _burstExpandTime + _burstFadeTime;
        float total = Mathf.Max(slashTotal, burstTotal);

        if (_timer >= total)
        {
            _playing = false;
            HideAll();
            return;
        }

        UpdateSlash();
        UpdateBurst();
    }

    private void UpdateSlash()
    {
        float t = _timer / _slashDrawTime;
        float drawT = Mathf.Clamp01(t);

        float alpha;
        if (_timer <= _slashDrawTime)
            alpha = 1f;
        else
            alpha = 1f - (_timer - _slashDrawTime) / _slashFadeTime;

        alpha = Mathf.Clamp01(alpha);

        if (alpha <= 0f)
        {
            _slashLr.enabled = false;
            return;
        }

        Vector3 tip = Vector3.Lerp(_startPos, _hitPos, drawT);

        _slashLr.enabled = true;
        _slashLr.positionCount = 2;
        _slashLr.SetPosition(0, _startPos);
        _slashLr.SetPosition(1, tip);

        Color c = _slashColor;
        _slashLr.startColor = new Color(c.r, c.g, c.b, alpha);
        _slashLr.endColor = new Color(c.r, c.g, c.b, alpha * 0.3f);
    }

    private void UpdateBurst()
    {
        // Burst starts slightly after the slash begins
        float burstStart = _slashDrawTime * 0.5f;
        float localT = _timer - burstStart;
        if (localT < 0f)
        {
            _burstLr.enabled = false;
            return;
        }

        float expandT = Mathf.Clamp01(localT / _burstExpandTime);

        float alpha;
        if (localT <= _burstExpandTime)
            alpha = 1f;
        else
            alpha = 1f - (localT - _burstExpandTime) / _burstFadeTime;

        alpha = Mathf.Clamp01(alpha);

        if (alpha <= 0f)
        {
            _burstLr.enabled = false;
            return;
        }

        float radius = Mathf.Lerp(0.05f, _burstMaxRadius, expandT);

        // Draw a starburst: rays alternating in/out from centre
        int points = _burstRays * 2;
        _burstLr.enabled = true;
        _burstLr.positionCount = points;
        _burstLr.loop = false;

        for (int i = 0; i < points; i++)
        {
            float angle = (i / (float)points) * Mathf.PI * 2f;
            float r = (i % 2 == 0) ? radius : radius * 0.4f;
            Vector3 offset = new Vector3(Mathf.Cos(angle) * r, 0f, Mathf.Sin(angle) * r);
            _burstLr.SetPosition(i, _hitPos + offset);
        }

        Color c = _burstColor;
        _burstLr.startColor = new Color(c.r, c.g, c.b, alpha);
        _burstLr.endColor = new Color(c.r, c.g, c.b, alpha * 0.5f);
    }

    private void HideAll()
    {
        _slashLr.enabled = false;
        _burstLr.enabled = false;
    }
}

