using UnityEngine;

/// <summary>
/// Concrete resource subscriber. Listens to <see cref="ResourceManager.OnResourceHit"/> and
/// forwards damage to its own <see cref="ResourceNode"/> when the hit targets this object
/// (or a child). This is the bridge between the observer pattern event pipe and the
/// health/damage system on <see cref="ResourceNode"/>.
/// </summary>
[RequireComponent(typeof(ResourceNode))]
public class StoneResource : MonoBehaviour
{
    private ResourceNode _node;

    private void Awake()
    {
        _node = GetComponent<ResourceNode>();
    }

    private void OnEnable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit += HandleHit;
        else
            Debug.LogWarning($"[StoneResource] No ResourceManager in scene; '{name}' won't receive hits.", this);
    }

    private void OnDisable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit -= HandleHit;
    }

    private void HandleHit(PlayerHitInfo info)
    {
        // Only react if the hit targets this stone (or one of its children)
        if (info.Target == null) return;
        if (!IsThisResource(info.Target)) return;

        _node.ReceiveHit(info.Power);
    }

    /// <summary>True if the target GameObject is this object or a descendant.</summary>
    private bool IsThisResource(GameObject target)
    {
        Transform t = target.transform;
        while (t != null)
        {
            if (t.gameObject == gameObject) return true;
            t = t.parent;
        }
        return false;
    }
}

