// Wire the Stone_Config to the Stone_Test's ResourceNode
var stone = UnityEngine.GameObject.Find("Stone_Test");
if (stone == null) { UnityEngine.Debug.LogError("Stone_Test not found"); return; }

var node = stone.GetComponent<ResourceNode>();
if (node == null) { UnityEngine.Debug.LogError("ResourceNode not found on Stone_Test"); return; }

var config = UnityEditor.AssetDatabase.LoadAssetAtPath<ResourceNodeConfig>("Assets/Flynn/Configs/Resources/Stone_Config.asset");
if (config == null) { UnityEngine.Debug.LogError("Stone_Config not found"); return; }

var so = new UnityEditor.SerializedObject(node);
so.FindProperty("_config").objectReferenceValue = config;
so.ApplyModifiedProperties();

UnityEngine.Debug.Log($"Wired Stone_Config to Stone_Test ResourceNode (requiredTool={config.requiredTool}, maxHealth={config.maxHealth})");

