using UnityEngine;

/// <summary>
/// Left-click swing for the wrench multitool. Tap = light swing; hold to charge and
/// release for a heavier swing (longer cooldown). The swing faces the mouse aim point.
/// When aimed at a ResourceNode the wrench "transforms" to that tool's attack animation,
/// otherwise it plays the plain wrench swing. Disabled while the wrench is airborne
/// (thrown). Exposes IsCharging / ChargeNormalized for the aim reticle.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchSwingController : MonoBehaviour
{
    private const int WrenchAnimIndex = 4;

    [SerializeField] private WrenchConfig _config;
    [Tooltip("Optional — used to block swinging while the wrench is mid-throw.")]
    [SerializeField] private WrenchThrowController _throw;

    [Tooltip("Directional swipe arc visual. Fed the player→mouse direction on each swing.")]
    [SerializeField] private WrenchSwingArc _swingArc;

    private IPlayerVisual _animDriver;

    [Tooltip("Delay from swing release to the hit landing (seconds). Tune for impact feel.")]
    [SerializeField] private float _hitDelay = 0.1f;

    private PlayerMouseAimer _aimer;
    private PlayerInitializer _playerInit;
    private float _cooldown;
    private float _chargeTimer;
    private bool _charging;

    // Queued hit: raised through ResourceManager after a short delay (impact timing).
    private Vector3 _pendingHitPoint;
    private GameObject _pendingHitTarget;
    private int _pendingDamage;
    private float _hitTimer;
    private bool _hitPending;

    public bool IsCharging => _charging;
    public float ChargeNormalized => _config != null && _config.swingChargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.swingChargeTime)
        : 0f;

    private void Awake()
    {
        _aimer     = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _playerInit = GetComponent<PlayerInitializer>();
    }

    private void Update()
    {
        if (_cooldown > 0f) _cooldown -= Time.deltaTime;

        // Apply a queued hit once its delay elapses.
        if (_hitPending)
        {
            _hitTimer -= Time.deltaTime;
            if (_hitTimer <= 0f) ApplyPendingHit();
        }

        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && (_throw == null || !_throw.IsAirborne);
        if (!usable)
        {
            // Wrench put away (or thrown) mid-charge: abort the frozen windup pose.
            if (_charging)
            {
                if (_animDriver != null) _animDriver.CancelSwing();
                _charging = false;
                _chargeTimer = 0f;
            }
            return;
        }

        if (Input.GetMouseButtonDown(0) && _cooldown <= 0f)
        {
            _charging = true;
            _chargeTimer = 0f;
            FaceAim();
            // Freeze the would-be tool on its windup frame; live-swapped while held.
            if (_animDriver != null) _animDriver.BeginChargePose(_aimer.SwingAnimIndex);
        }
        else if (_charging && Input.GetMouseButton(0))
        {
            _chargeTimer += Time.deltaTime;
            FaceAim();
            if (_animDriver != null) _animDriver.UpdateChargePose(_aimer.SwingAnimIndex, ChargeNormalized);
        }
        else if (_charging && Input.GetMouseButtonUp(0))
        {
            DoSwing();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void FaceAim()
    {
        if (_animDriver != null)
            _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);
    }

    private void DoSwing()
    {
        if (_animDriver == null) return;

        FaceAim();

        // Tool comes from the surface under the cursor within melee reach (4 = wrench/air).
        int animIndex = _aimer.SwingAnimIndex;
        if (animIndex <= 0) animIndex = WrenchAnimIndex;

        float charge = ChargeNormalized;
        bool heavy = charge >= (_config != null ? _config.heavySwingThreshold : 0.6f);

        // More charge → faster follow-through (the stored power releasing).
        float lightSpd = _config != null ? _config.lightSwingAnimSpeed : 1.0f;
        float heavySpd = _config != null ? _config.heavySwingAnimSpeed : 2.5f;
        _animDriver.ReleaseSwing(animIndex, Mathf.Lerp(lightSpd, heavySpd, charge));

        // Show the directional swipe arc toward the aim point.
        if (_swingArc != null)
            _swingArc.Play(_aimer.WorldAimPoint);

        _cooldown = heavy
            ? (_config != null ? _config.heavySwingCooldown : 0.8f)
            : (_config != null ? _config.lightSwingCooldown : 0.45f);

        // Route damage through the ResourceManager observer pattern.
        // Capture target + damage now, raise after a short delay (impact feel).
        int damage = heavy
            ? (_config != null ? _config.heavySwingDamage : 2)
            : (_config != null ? _config.lightSwingDamage : 1);

        _pendingHitPoint = _aimer.WorldAimPoint;
        _pendingHitTarget = _aimer.HoveredGameObject;
        _pendingDamage = damage;
        _hitTimer = _hitDelay;
        _hitPending = true;
    }

    private void ApplyPendingHit()
    {
        _hitPending = false;
        if (_playerInit != null && _pendingDamage > 0)
            _playerInit.EmitHit(_pendingHitPoint, _pendingHitTarget, _pendingDamage);
        _pendingHitTarget = null;
        _pendingDamage = 0;
    }
}

using System;
using UnityEngine;

/// <summary>
/// Single source of truth for the mouse pointer. One per scene (lives on the UI manager object).
/// Every frame it reads the cursor, builds ONE world ray, and casts ONCE against a combined layer
/// mask — then caches the result. Gameplay and UI read these cached values instead of each running
/// their own <c>Camera.ScreenPointToRay(Input.mousePosition)</c> + <c>Physics.Raycast</c>.
///
/// Same hub idea as the other managers: record the signal once, everyone else just reads it. Runs
/// early (negative execution order) so the cache is fresh before any default-order consumer's Update.
/// </summary>
[DefaultExecutionOrder(-90)]
public class MousePointer : MonoBehaviour
{
    public static MousePointer Instance { get; private set; }

    [Tooltip("Camera the cursor ray is built from. Falls back to Camera.main.")]
    [SerializeField] private Camera _camera;
    [Tooltip("Combined mask for the per-frame world cast — the union of everything UI/gameplay needs.")]
    [SerializeField] private LayerMask _worldMask = ~0;
    [SerializeField] private float _maxDistance = 100f;

    // ── Cached each frame ───────────────────────────────────────────────────────

    /// <summary>Cursor position in screen pixels (== Input.mousePosition).</summary>
    public Vector2 ScreenPosition { get; private set; }
    /// <summary>Ray from the camera through the cursor.</summary>
    public Ray WorldRay { get; private set; }
    /// <summary>True if this frame's cast hit a collider on <see cref="_worldMask"/>.</summary>
    public bool HasHit { get; private set; }
    /// <summary>This frame's raycast hit (valid only when <see cref="HasHit"/>).</summary>
    public RaycastHit Hit { get; private set; }
    /// <summary>Hit point if we hit, else the ray projected to max distance (always usable as an aim target).</summary>
    public Vector3 WorldPoint { get; private set; }
    /// <summary>Collider under the cursor this frame, or null.</summary>
    public Collider HoverCollider { get; private set; }
    /// <summary>GameObject under the cursor this frame, or null.</summary>
    public GameObject HoverObject { get; private set; }

    /// <summary>Fires when the hovered GameObject changes (including to/from null).</summary>
    public event Action<GameObject> OnHoverChanged;

    private GameObject _lastHover;

    // ── Public helpers ──────────────────────────────────────────────────────────

    /// <summary>True when the current hover object sits on one of the given layers.</summary>
    public bool HoverOnLayers(LayerMask mask)
        => HoverObject != null && (mask.value & (1 << HoverObject.layer)) != 0;

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[MousePointer] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
        if (_camera == null) _camera = Camera.main;
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (_camera == null)
        {
            _camera = Camera.main;
            if (_camera == null) return;
        }

        ScreenPosition = Input.mousePosition;
        WorldRay = _camera.ScreenPointToRay(ScreenPosition);

        HasHit = Physics.Raycast(WorldRay, out RaycastHit hit, _maxDistance, _worldMask, QueryTriggerInteraction.Ignore);
        Hit = hit;

        if (HasHit)
        {
            WorldPoint = hit.point;
            HoverCollider = hit.collider;
            HoverObject = hit.collider != null ? hit.collider.gameObject : null;
        }
        else
        {
            WorldPoint = WorldRay.GetPoint(_maxDistance);
            HoverCollider = null;
            HoverObject = null;
        }

        if (HoverObject != _lastHover)
        {
            _lastHover = HoverObject;
            OnHoverChanged?.Invoke(HoverObject);
        }
    }
}

