// Quick diagnostic: check the MousePointer layer mask and what it sees when aimed at the stone
var mp = MousePointer.Instance;
if (mp == null) { UnityEngine.Debug.LogError("No MousePointer in scene"); return; }

var so = new UnityEditor.SerializedObject(mp);
var maskProp = so.FindProperty("_worldMask");
int mask = maskProp != null ? maskProp.intValue : -1;

UnityEngine.Debug.Log($"MousePointer worldMask layers: {UnityEngine.LayerMask.LayerToName(mask)} (raw={mask})");
UnityEngine.Debug.Log($"MousePointer camera: {mp.GetType().GetField("_camera", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)?.GetValue(mp)}");

// Check the stone's layer
var stone = UnityEngine.GameObject.Find("Stone_Test");
UnityEngine.Debug.Log($"Stone_Test layer: {stone.layer} ({UnityEngine.LayerMask.LayerToName(stone.layer)})");
UnityEngine.Debug.Log($"Stone_Test collider: {stone.GetComponent<UnityEngine.Collider>()?.name ?? "none"}");

// Test raycast manually
var cam = UnityEngine.Camera.main;
var ray = cam.ScreenPointToRay(UnityEngine.Input.mousePosition);
if (UnityEngine.Physics.Raycast(ray, out var hit, 100f, mask, UnityEngine.QueryTriggerInteraction.Ignore))
{
    UnityEngine.Debug.Log($"Manual raycast hit: {hit.collider.gameObject.name} (layer={hit.collider.gameObject.layer}) at {hit.point}");
}
else
{
    UnityEngine.Debug.Log("Manual raycast: nothing hit");
}

