// Add Default (layer 0) to the existing mask
int current = maskProp.intValue;
int withDefault = current | (1 << 0);
maskProp.intValue = withDefault;
so.ApplyModifiedProperties();

UnityEngine.Debug.Log($"MousePointer worldMask: {current} -> {withDefault} (added Default layer)");

