/* ============================================================
   IntroSequence.uss
   Prototype intro text panel (UI Toolkit)
   ============================================================

   Design tokens (inlined values):
   --bg-overlay      : rgba(6, 8, 10, 0.30)
   --panel-bg        : rgba(14, 18, 24, 0.88)
   --panel-border    : rgba(102, 170, 150, 0.95)
   --text-main       : rgba(234, 239, 243, 1.00)
   --text-hint       : rgba(197, 208, 214, 0.86)
   --hint-pill-bg    : rgba(102, 170, 150, 0.20)

   Spacing scale: 8 / 12 / 16 / 24 / 32 px
   Type scale:    16px / 20px / 22px
   ============================================================ */

/* Visibility toggles for C# class switching */
.is-hidden {
    display: none;
}

.is-visible {
    display: flex;
}

.skip-hint-hidden {
    display: none;
}

/* Fullscreen anchor layer */
.intro-sequence {
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;

    justify-content: center;
    align-items: center;
    padding-bottom: 0;

    background-color: rgba(0, 0, 0, 1);
}

/* Story card */
.intro-frame {
    width: 88%;
    max-width: 1480px;
    min-height: 360px;
    opacity: 1;
    transition-property: opacity;
    transition-duration: 0.22s;
    transition-timing-function: ease-in-out;

    padding-top: 40px;
    padding-right: 44px;
    padding-bottom: 30px;
    padding-left: 44px;

    background-color: rgba(0, 0, 0, 0.12);
    border-top-width: 6px;
    border-right-width: 6px;
    border-bottom-width: 6px;
    border-left-width: 6px;
    border-color: rgba(255, 255, 255, 1);
    border-top-left-radius: 0;
    border-top-right-radius: 0;
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;

    flex-direction: column;
    justify-content: flex-start;
}

.intro-frame.frame-faded {
    opacity: 0;
}

/* Main typewriter text */
.intro-story-label {
    flex-grow: 1;
    min-height: 220px;
    opacity: 1;
    transition-property: opacity;
    transition-duration: 0.22s;
    transition-timing-function: ease-in-out;

    color: rgba(255, 255, 255, 1.0);
    font-size: 52px;
    -unity-font-style: bold;
    -unity-text-outline-width: 2px;
    -unity-text-outline-color: rgba(0, 0, 0, 1.0);
    -unity-text-align: middle-center;
    white-space: normal;
}

.intro-story-label.story-faded {
    opacity: 0;
}

/* Bottom-right skip hint */
.intro-skip-hint-label {
    align-self: center;
    margin-top: 18px;

    padding-top: 6px;
    padding-right: 14px;
    padding-bottom: 6px;
    padding-left: 14px;

    background-color: rgba(0, 0, 0, 0.35);
    border-top-width: 2px;
    border-right-width: 2px;
    border-bottom-width: 2px;
    border-left-width: 2px;
    border-color: rgba(255, 255, 255, 0.75);
    border-top-left-radius: 0;
    border-top-right-radius: 0;
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;

    color: rgba(255, 255, 255, 0.82);
    font-size: 20px;
    -unity-font-style: bold;
    -unity-text-outline-width: 1px;
    -unity-text-outline-color: rgba(0, 0, 0, 1.0);
    -unity-text-align: middle-center;
    white-space: nowrap;
}

/* Lightweight responsive adjustment for 720p-ish layouts */
.intro-sequence.compact .intro-frame {
    min-height: 260px;
    padding-top: 24px;
    padding-right: 24px;
    padding-bottom: 20px;
    padding-left: 24px;
}

.intro-sequence.compact .intro-story-label {
    min-height: 150px;
    font-size: 36px;
}

.intro-sequence.compact .intro-skip-hint-label {
    font-size: 16px;
}

using UnityEngine;

/// <summary>
/// The single droppable / pickupable unit in the world: an <see cref="ItemDefinition"/> plus a
/// stack count. Everything that can sit on the ground — resource drops, echo shards, the wrench,
/// items dropped from the inventory — is a WorldItem. Auto-collecting items are pulled in by
/// <see cref="DroppedItemMagnet"/>; non-auto items (the wrench) are picked up with the pickup key
/// via <see cref="PlayerMouseAimer"/>/<see cref="PlayerPickupController"/>.
///
/// Detection is by mouse raycast (solid, non-trigger collider on the pickup layer) — no registry.
/// </summary>
[RequireComponent(typeof(Collider))]
public class WorldItem : MonoBehaviour, IInteractionPromptProvider
{
    [Tooltip("Item this world object represents.")]
    [SerializeField] private ItemDefinition _item;

    [Tooltip("How many of the item this stack holds.")]
    [SerializeField] private int _count = 1;

    public ItemDefinition Item => _item;
    public int Count => _count;

    /// <summary>Set the item + count, e.g. when spawned by <see cref="WorldItemSpawner"/>.</summary>
    public void Configure(ItemDefinition item, int count)
    {
        _item = item;
        _count = Mathf.Max(1, count);
    }

    /// <summary>Reduce the stack after a partial collection; returns the remaining count.</summary>
    public int Reduce(int amount)
    {
        _count = Mathf.Max(0, _count - Mathf.Max(0, amount));
        return _count;
    }

    // Only key-pickup items prompt; auto-collect drops fly in on their own (no prompt).
    public bool TryGetPrompt(out InteractionPrompt prompt)
    {
        if (_item == null || _item.AutoCollects)
        {
            prompt = default;
            return false;
        }
        prompt = new InteractionPrompt("E", "Pick Up", transform, _item.displayName);
        return true;
    }
}

using UnityEngine;

/// <summary>The flavour of a rope anchor. Cosmetic / future tuning hook.</summary>
public enum AnchorType { Stub, Stone, Rock }

/// <summary>
/// Marks a world object the rope lasso can latch onto and reel the player toward.
/// Detection is by mouse raycast in <see cref="PlayerMouseAimer"/> — no registry, no
/// trigger volume. The collider must be a SOLID (non-trigger) collider on a layer in the
/// aimer's grapple mask so the ray can hit it; the lasso latches on the exact hit point.
/// </summary>
[RequireComponent(typeof(Collider))]
public class RopeAnchor : MonoBehaviour, IInteractionPromptProvider
{
    [Tooltip("Cosmetic anchor flavour; reserved for future per-type tuning.")]
    [SerializeField] private AnchorType _type = AnchorType.Stub;

    public AnchorType Type => _type;

    public bool TryGetPrompt(out InteractionPrompt prompt)
    {
        prompt = new InteractionPrompt("Q", "Grapple", transform);
        return true;
    }
}

using UnityEngine;

/// <summary>
/// Marks a movable world object the rope lasso can reel toward the player. Detection is by
/// mouse raycast in <see cref="PlayerMouseAimer"/> — no registry, no separate detection
/// trigger. The object's solid (non-trigger) collider must sit on a layer in the aimer's
/// grapple mask so the ray can hit it. The reel applies force to this Rigidbody.
/// </summary>
[RequireComponent(typeof(Rigidbody))]
[RequireComponent(typeof(Collider))]
public class RopePullable : MonoBehaviour, IInteractionPromptProvider
{
    public Rigidbody Body { get; private set; }

    private void Awake() => Body = GetComponent<Rigidbody>();

    public bool TryGetPrompt(out InteractionPrompt prompt)
    {
        prompt = new InteractionPrompt("Q", "Grapple", transform);
        return true;
    }
}

