using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Single scene driver for <see cref="WorldInteractTag"/>. Reads the one hover source
/// (<see cref="PlayerMouseAimer.HoveredInteractable"/>) each frame and shows the hovered
/// interactable's tag with its prompt text, hiding the previously-hovered one. Because hover is
/// resolved once in the aimer, exactly one tag is visible at a time and no tag runs its own raycast.
///
/// Drop one of these in the scene (e.g. on the player or a UI/Managers object) and assign the aimer.
/// </summary>
public class WorldInteractTagPresenter : MonoBehaviour
{
    [SerializeField] private PlayerMouseAimer _aimer; // falls back to a one-time scene find

    // Provider → its tag (or null if it has none). Cached so we GetComponent once per interactable.
    private readonly Dictionary<IInteractionPromptProvider, WorldInteractTag> _tags = new();
    private WorldInteractTag _shown;

    private void Awake()
    {
        if (_aimer == null) _aimer = FindObjectOfType<PlayerMouseAimer>();
    }

    private void LateUpdate()
    {
        if (_aimer == null) return;

        IInteractionPromptProvider hovered = _aimer.HoveredInteractable;
        WorldInteractTag tag = hovered != null && hovered.TryGetPrompt(out InteractionPrompt prompt) && prompt.IsValid
            ? Resolve(hovered)
            : null;

        if (tag == _shown)
        {
            // Same target still hovered — refresh text in case the prompt changed (e.g. count).
            if (tag != null && hovered.TryGetPrompt(out InteractionPrompt p)) tag.Show(p.Display);
            return;
        }

        if (_shown != null) _shown.Hide();
        if (tag != null && hovered.TryGetPrompt(out InteractionPrompt cur)) tag.Show(cur.Display);
        _shown = tag;
    }

    /// <summary>Find (and cache) the tag on a hovered provider's GameObject or its children.</summary>
    private WorldInteractTag Resolve(IInteractionPromptProvider provider)
    {
        if (_tags.TryGetValue(provider, out WorldInteractTag cached)) return cached;

        WorldInteractTag tag = provider is Component c ? c.GetComponentInChildren<WorldInteractTag>(true) : null;
        _tags[provider] = tag;
        return tag;
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Reusable world-space interaction tag. Drop this component on any interactable that implements
/// <see cref="IInteractionPromptProvider"/>. On first show it spawns a billboarded label styled in
/// the Flynn monochrome design: black box, 1px white outline, white text — matching the rest of
/// the UI (hotbar, dialogue, HUD).
///
/// It does NOT detect hover itself. <see cref="WorldInteractTagPresenter"/> reads the single hover
/// source (<see cref="PlayerMouseAimer.HoveredInteractable"/>) and calls <see cref="Show"/> /
/// <see cref="Hide"/> on the hovered object's tag.
/// </summary>
public class WorldInteractTag : MonoBehaviour
{
    [Tooltip("Local offset of the tag above the interactable's origin (world units, Y up).")]
    [SerializeField] private Vector3 _worldOffset = new Vector3(0f, 1.5f, 0f);
    [Tooltip("TMP point size of the world label.")]
    [SerializeField] private float _fontSize = 1.6f;
    [Tooltip("Optional pre-authored label child. Leave empty to auto-build one at runtime.")]
    [SerializeField] private TextMeshPro _label;

    private Transform _tagRoot;
    private SpriteRenderer _bgSprite;

    /// <summary>True while the tag is currently displayed.</summary>
    public bool IsShown => _tagRoot != null && _tagRoot.gameObject.activeSelf;

    /// <summary>Show the tag with the given display text (e.g. the prompt's Display string).</summary>
    public void Show(string text)
    {
        EnsureBuilt();
        if (_label != null) _label.text = text;
        if (_tagRoot != null) _tagRoot.gameObject.SetActive(true);
    }

    /// <summary>Hide the tag. Safe to call when already hidden.</summary>
    public void Hide()
    {
        if (_tagRoot != null) _tagRoot.gameObject.SetActive(false);
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private void EnsureBuilt()
    {
        if (_tagRoot != null) return;

        if (_label != null)
        {
            _tagRoot = _label.transform;
            return;
        }

        // Root object
        var go = new GameObject("InteractTag");
        _tagRoot = go.transform;
        _tagRoot.SetParent(transform, worldPositionStays: false);
        _tagRoot.localPosition = _worldOffset;
        go.AddComponent<Billboard>();

        // Background panel: black fill + white outline ( Flynn mono style )
        var bgGo = new GameObject("Bg");
        bgGo.transform.SetParent(_tagRoot, false);
        bgGo.transform.localPosition = Vector3.zero;

        _bgSprite = bgGo.AddComponent<SpriteRenderer>();
        // 1px-white-square sprite tinted per-instance
        _bgSprite.sprite = CreateWhitePixel();
        _bgSprite.color = Color.black;
        _bgSprite.drawMode = SpriteDrawMode.Sliced;
        _bgSprite.size = new Vector2(1.5f, 0.3f);
        // Sort behind the text
        _bgSprite.sortingOrder = -1;

        // White outline: same sprite, slightly larger, drawn behind the black fill
        var outlineGo = new GameObject("Outline");
        outlineGo.transform.SetParent(_tagRoot, false);
        outlineGo.transform.localPosition = Vector3.zero;

        var outlineSprite = outlineGo.AddComponent<SpriteRenderer>();
        outlineSprite.sprite = _bgSprite.sprite;
        outlineSprite.color = Color.white;
        outlineSprite.drawMode = SpriteDrawMode.Sliced;
        outlineSprite.size = new Vector2(1.58f, 0.38f); // +0.04 per side ≈ 1px outline
        outlineSprite.sortingOrder = -2;

        // Text label
        var labelGo = new GameObject("Label");
        labelGo.transform.SetParent(_tagRoot, false);
        labelGo.transform.localPosition = Vector3.zero;

        _label = labelGo.AddComponent<TextMeshPro>();
        _label.text = string.Empty;
        _label.fontSize = _fontSize;
        _label.color = Color.white;
        _label.alignment = TextAlignmentOptions.Center;
        _label.enableWordWrapping = false;

        var rt = _label.rectTransform;
        rt.sizeDelta = new Vector2(3f, 0.75f);

        go.SetActive(false);
    }

    /// <summary>1×1 white pixel sprite for sliced rendering.</summary>
    private static Sprite CreateWhitePixel()
    {
        var tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
        tex.SetPixel(0, 0, Color.white);
        tex.Apply();
        tex.name = "TagPixel";
        var sprite = Sprite.Create(tex, Rect.MinMaxRect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);
        sprite.name = "TagPixel";
        return sprite;
    }
}

