}

.interact-tag__label {
    color: rgb(255, 255, 255);
    font-size: 12px;
    -unity-text-align: middle-center;
    white-space: nowrap;
}

using UnityEngine;
using UnityEngine.UIElements;

/// <summary>
/// Screen-space interaction tag that tracks a world anchor. Driven by
/// <see cref="WorldInteractTagPresenter"/>: when a hover is active, the presenter
/// calls <see cref="ShowAt"/> with the anchor's screen position and prompt text.
/// When nothing is hovered, the presenter calls <see cref="HideTag"/>.
///
/// Lives as a pre-existing UIDocument under the UI manager so designers can
/// customise the UXML/USS. Uses the Flynn mono palette (black bg, 1px white outline).
/// </summary>
public class InteractTagPanel : UIToolkitPanel
{
    [Tooltip("Camera used for world→screen projection. Falls back to Camera.main.")]
    [SerializeField] private Camera _camera;

    private Label _label;
    private VisualElement _root;

    /// <summary>World-space anchor that the tag follows, or null when hidden.</summary>
    private Transform _anchor;
    private Vector3 _anchorOffset;

    protected override void Awake()
    {
        base.OnEnable();
        if (_camera == null) _camera = Camera.main;
    }

    protected override bool Bind(VisualElement root)
    {
        _root = root.Q<VisualElement>("InteractTagRoot");
        _label = root.Q<Label>("InteractTagLabel");
        return _root != null && _label != null;
    }

    private void LateUpdate()
    {
        if (_anchor == null || !IsVisible) return;

        // Project world anchor to screen space and position the tag
        if (_camera == null) _camera = Camera.main;
        if (_camera == null) return;

        Vector3 worldPos = _anchor.position + _anchorOffset;
        Vector2 screen = RuntimePanelUtils.CameraToScreenPoint(_root.panel, _camera, worldPos);

        // Convert from screen pixels to panel pixels
        _root.style.left = screen.x;
        _root.style.top = screen.y;
    }

    /// <summary>Show the tag anchored to a world transform.</summary>
    /// <param name="anchor">World transform to track (e.g. the interactable).</param>
    /// <param name="worldOffset">Offset from the anchor's position (e.g. 1.5 units up).</param>
    /// <param name="text">Prompt text to display.</param>
    public void ShowAt(Transform anchor, Vector3 worldOffset, string text)
    {
        _anchor = anchor;
        _anchorOffset = worldOffset;
        if (_label != null) _label.text = text;
        if (_root != null) _root.style.display = DisplayStyle.Flex;
        IsVisible = true;
    }

    /// <summary>Hide the tag.</summary>
    public void HideTag()
    {
        _anchor = null;
        if (_root != null) _root.style.display = DisplayStyle.None;
        IsVisible = false;
    }
}

using UnityEngine;

/// <summary>
/// Drives the <see cref="InteractTagPanel"/> from the hover source. Reads
/// <see cref="PlayerMouseAimer.HoveredInteractable"/> each frame and positions the
/// panel at the interactable's world anchor with its prompt text. When nothing is
/// hovered the tag is hidden.
///
/// The tag is a pre-existing UIDocument under the UI manager, customisable via UXML/USS.
/// This presenter only shows/hides it and updates the anchor position and text.
/// </summary>
public class WorldInteractTagPresenter : MonoBehaviour
{
    [SerializeField] private PlayerMouseAimer _aimer;
    [SerializeField] private InteractTagPanel _tagPanel;

    private void Awake()
    {
        if (_aimer == null) _aimer = FindObjectOfType<PlayerMouseAimer>();
        if (_tagPanel == null) _tagPanel = FindObjectOfType<InteractTagPanel>();
    }

    private void LateUpdate()
    {
        if (_aimer == null || _tagPanel == null) return;

        IInteractionPromptProvider hovered = _aimer.HoveredInteractable;

        if (hovered != null && hovered.TryGetPrompt(out InteractionPrompt prompt) && prompt.IsValid)
        {
            Transform anchor = prompt.Anchor != null ? prompt.Anchor
                : hovered is Component c ? c.transform : null;

            if (anchor != null)
            {
                Vector3 offset = anchor.GetComponent<WorldInteractTag>()?.WorldOffset
                    ?? new Vector3(0f, 1.5f, 0f);
                _tagPanel.ShowAt(anchor, offset, prompt.Display);
            }
        }
        else
        {
            _tagPanel.HideTag();
        }
    }
}

using UnityEngine;

/// <summary>
/// Marks an interactable with a world-space offset for the interaction tag label.
/// Drop this on any interactable that implements <see cref="IInteractionPromptProvider"/>
/// to control where the hover tag appears relative to the object's origin.
///
/// The tag itself is rendered by <see cref="InteractTagPanel"/> (a UIDocument under the
/// UI manager), not by this component. This component only provides the offset.
/// </summary>
public class WorldInteractTag : MonoBehaviour
{
    [Tooltip("Local offset of the tag above the interactable's origin (world units, Y up).")]
    [SerializeField] private Vector3 _worldOffset = new Vector3(0f, 1.5f, 0f);

    /// <summary>World-space offset for the tag anchor.</summary>
    public Vector3 WorldOffset => _worldOffset;
}

