args.script:
var go = UnityEngine.GameObject.Find("UI/InteractTag");
if (go == null) { UnityEngine.Debug.LogError("InteractTag not found"); return; }

// Add UIDocument
var uidoc = go.AddComponent<UnityEngine.UIElements.UIDocument>();

// Load the UXML asset
var uxml = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.UIElements.VisualTreeAsset>(
    "Assets/Flynn/UI/Screens/InteractTag/InteractTag.uxml");
if (uxml != null) uidoc.visualTreeAsset = uxml;
else UnityEngine.Debug.LogWarning("UXML not found");

// Set panel settings — use the same PanelSettings as PlayerHud
var hudPanel = UnityEngine.GameObject.Find("UI/PlayerHud");
var hudDoc = hudPanel?.GetComponent<UnityEngine.UIElements.UIDocument>();
if (hudDoc != null && hudDoc.panelSettings != null)
{
    uidoc.panelSettings = hudDoc.panelSettings;
    UnityEngine.Debug.Log("Using same PanelSettings as PlayerHud");
}

// Add InteractTagPanel
var panel = go.AddComponent<InteractTagPanel>();

// Set the panel ID
var so = new UnityEditor.SerializedObject(panel);
so.FindProperty("_panelId").intValue = 5; // InteractTag
so.FindProperty("_startVisible").boolValue = false;
so.ApplyModifiedProperties();

UnityEngine.Debug.Log("InteractTag panel created and configured");

