using UnityEngine;
using UnityEngine.UIElements;

/// <summary>
/// Screen-space interaction tag that tracks a world anchor. Driven by
/// <see cref="WorldInteractTagPresenter"/>: when a hover is active, the presenter
/// calls <see cref="ShowAt"/> with the anchor's screen position and prompt text.
/// When nothing is hovered, the presenter calls <see cref="HideTag"/>.
///
/// Lives as a pre-existing UIDocument under the UI manager so designers can
/// customise the UXML/USS. Uses the Flynn mono palette (black bg, 1px white outline).
/// </summary>
public class InteractTagPanel : UIToolkitPanel
{
    [Tooltip("Camera used for world→screen projection. Falls back to Camera.main.")]
    [SerializeField] private Camera _camera;

    private Label _label;
    private VisualElement _root;

    /// <summary>World-space anchor that the tag follows, or null when hidden.</summary>
    private Transform _anchor;
    private Vector3 _anchorOffset;

    protected override void Awake()
    {
        base.OnEnable();
        if (_camera == null) _camera = Camera.main;
    }

    protected override bool Bind(VisualElement root)
    {
        _root = root.Q<VisualElement>("InteractTagRoot");
        _label = root.Q<Label>("InteractTagLabel");
        return _root != null && _label != null;
    }

    private void LateUpdate()
    {
        if (_anchor == null || !IsVisible || _root == null) return;

        if (_camera == null) _camera = Camera.main;
        if (_camera == null) return;

        Vector3 worldPos = _anchor.position + _anchorOffset;
        Vector3 screen = _camera.WorldToScreenPoint(worldPos);

        // UI Toolkit origin is top-left; screen space origin is bottom-left
        _root.style.left = screen.x;
        _root.style.top = Screen.height - screen.y;
    }

    /// <summary>Show the tag anchored to a world transform.</summary>
    /// <param name="anchor">World transform to track (e.g. the interactable).</param>
    /// <param name="worldOffset">Offset from the anchor's position (e.g. 1.5 units up).</param>
    /// <param name="text">Prompt text to display.</param>
    public void ShowAt(Transform anchor, Vector3 worldOffset, string text)
    {
        _anchor = anchor;
        _anchorOffset = worldOffset;
        if (_label != null) _label.text = text;
        if (_root != null) _root.style.display = DisplayStyle.Flex;
        IsVisible = true;
    }

    /// <summary>Hide the tag.</summary>
    public void HideTag()
    {
        _anchor = null;
        if (_root != null) _root.style.display = DisplayStyle.None;
        IsVisible = false;
    }
}

