private void LateUpdate()
{
    if (_anchor == null || !IsVisible || _root == null) return;

    if (_camera == null) _camera = Camera.main;
    if (_camera == null) return;

    Vector3 worldPos = _anchor.position + _anchorOffset;
    Vector3 screen = _camera.WorldToScreenPoint(worldPos);

    // Convert screen pixels to panel coordinates.
    // PanelSettings scaleMode controls the DPI scaling factor.
    var panel = _root.panel;
    if (panel == null) return;

    // Get the panel's content container size for coordinate mapping
    var contentRect = panel.visualTree.layout;
    float scaleX = contentRect.width > 0 ? Screen.width / contentRect.width : 1f;
    float scaleY = contentRect.height > 0 ? Screen.height / contentRect.height : 1f;

    _root.style.left = screen.x / scaleX;
    _root.style.top = (Screen.height - screen.y) / scaleY;
}

